SELECT * FROM (SELECT * FROM (SELECT 'TX:' || t.transaction_id event_id, t.warehouse_number case_id, 'Goods Received' activity, t.occurred_at timestamp FROM transaction_record t WHERE t.transaction_type='IN' UNION ALL SELECT 'TX:' || t.transaction_id event_id, t.warehouse_number case_id, 'Goods Dispatched' activity, t.occurred_at timestamp FROM transaction_record t WHERE t.transaction_type='OUT') UNION ALL SELECT e.event_id,l.case_id,e.activity,e.timestamp FROM (SELECT event_id,activity,occurred_at timestamp FROM transaction_record_activity) e JOIN lifecycle_case_link l ON l.event_id=e.event_id WHERE l.case_table='warehouse') ORDER BY case_id,timestamp,event_id;
